from hermes_tools import terminal
cmd = "python3 -c "from collections import deque; g=['..###.','###.#.','#...#.','##..#.','.#..##','.#...#','.#####']; H=len(g);W=len(g[0]); s={(r,c) for r in range(H) for c in range(W) if g[r][c]=='#'};
for adj in [4,8]:
 q=set(s); cs=[];
 while q:
  p=q.pop(); comp={p}; st=[p];
  while st:
   r,c=st.pop();
   for dr in [-1,0,1]:
    for dc in [-1,0,1]:
     if not (dr or dc) or (adj==4 and abs(dr)+abs(dc)!=1): continue
     z=(r+dr,c+dc);
     if z in q: q.remove(z); comp.add(z);st.append(z)
  cs.append(len(comp))
 print(adj,cs)""
print(terminal(cmd, timeout=10))

